export const LEETCODE_CATALOG: readonly LeetCodeCatalogEntry[] = RAW.split("\n").map((line) => {
  const [slug, title, difficulty, paid] = line.split("\t")
  return {
    slug: slug ?? "",
    title: title ?? slug ?? "",
    difficulty: (difficulty === "easy" || difficulty === "medium" || difficulty === "hard" ? difficulty : "medium"),
    paidOnly: paid === "1",
  }
})
